let accordions=document.querySelectorAll(".accordion__title");for(let t=0;t<accordions.length;t++)accordions[t].addEventListener("click",function(){this.classList.contains("active_faq_question")?this.classList.remove("active_faq_question"):(accordions.forEach(t=>{t.classList.remove("active_faq_question");t=t.nextElementSibling;t.style.maxHeight&&(t.style.maxHeight=null)}),this.classList.add("active_faq_question")),contentAction(this)});function contentAction(t){t=t.nextElementSibling;t.style.maxHeight?t.style.maxHeight=null:t.style.maxHeight=t.scrollHeight+"px"}